{
  "openapi": "3.1.0",
  "info": {
    "title": "Query Builder API",
    "version": "1.0.0",
    "description": "Universal SQL Query Builder, Declarative Compiler, and AST Safety Microservice."
  },
  "paths": {
    "/health": {
      "get": {
        "summary": "Health Check",
        "responses": {
          "200": {
            "description": "Server health status"
          }
        }
      }
    },
    "/openapi.json": {
      "get": {
        "summary": "OpenAPI Specification",
        "responses": {
          "200": {
            "description": "OpenAPI 3.1 document"
          }
        }
      }
    },
    "/docs": {
      "get": {
        "summary": "Swagger UI Documentation",
        "responses": {
          "200": {
            "description": "Swagger UI HTML"
          }
        }
      }
    },
    "/api/v1/introspect": {
      "post": {
        "summary": "Introspect Database Schema",
        "responses": {
          "200": {
            "description": "Schema snapshot"
          },
          "400": {
            "description": "Introspection error"
          }
        }
      }
    },
    "/api/v1/compile": {
      "post": {
        "summary": "Compile Query Specification",
        "responses": {
          "200": {
            "description": "Compiled SQL and parameters"
          },
          "400": {
            "description": "Compilation error"
          },
          "403": {
            "description": "Forbidden by security policy"
          }
        }
      }
    },
    "/api/v1/validate": {
      "post": {
        "summary": "Validate SQL AST",
        "responses": {
          "200": {
            "description": "Validation result"
          },
          "400": {
            "description": "Validation error"
          }
        }
      }
    },
    "/api/v1/execute": {
      "post": {
        "summary": "Execute Query",
        "responses": {
          "200": {
            "description": "Query result"
          },
          "400": {
            "description": "Execution error"
          },
          "403": {
            "description": "Forbidden by security policy"
          }
        }
      }
    },
    "/api/v1/query/execute": {
      "post": {
        "summary": "Execute Live Query with Connection Pool",
        "responses": {
          "200": {
            "description": "Live query execution result"
          },
          "400": {
            "description": "Execution error or cancellation"
          }
        }
      }
    },
    "/api/v1/connections": {
      "get": {
        "summary": "List Registered Connection Pools",
        "responses": {
          "200": {
            "description": "List of connection pools"
          }
        }
      },
      "post": {
        "summary": "Register New Connection Pool",
        "responses": {
          "201": {
            "description": "Connection pool registered"
          }
        }
      },
      "delete": {
        "summary": "Remove Connection Pool",
        "responses": {
          "200": {
            "description": "Connection pool removed"
          }
        }
      }
    },
    "/api/v1/connections/test": {
      "post": {
        "summary": "Test Connection Health & Latency",
        "responses": {
          "200": {
            "description": "Connection test result"
          }
        }
      }
    },
    "/api/v1/connections/cancel": {
      "post": {
        "summary": "Cancel In-Flight Query Execution",
        "responses": {
          "200": {
            "description": "Cancellation result"
          }
        }
      }
    },
    "/api/v1/stream": {
      "post": {
        "summary": "Stream Query Execution via Server-Sent Events",
        "responses": {
          "200": {
            "description": "Server-Sent Events stream"
          },
          "400": {
            "description": "Streaming error"
          },
          "403": {
            "description": "Forbidden by security policy"
          }
        }
      }
    },
    "/api/v1/explain": {
      "post": {
        "summary": "Explain and Analyze Query Plan",
        "responses": {
          "200": {
            "description": "Normalized QueryPlanNode tree"
          },
          "400": {
            "description": "Explain error"
          }
        }
      }
    },
    "/api/v1/export": {
      "post": {
        "summary": "Export Tabular Data",
        "responses": {
          "200": {
            "description": "Exported tabular file"
          },
          "400": {
            "description": "Export error"
          }
        }
      }
    },
    "/api/v1/export/stream": {
      "post": {
        "summary": "Stream Tabular Data Export with Chunked Transfer Encoding",
        "responses": {
          "200": {
            "description": "Chunked binary/text stream download"
          },
          "400": {
            "description": "Streaming export error"
          }
        }
      }
    },
    "/api/v1/templates": {
      "get": {
        "summary": "List Templates",
        "responses": {
          "200": {
            "description": "List of templates"
          }
        }
      },
      "post": {
        "summary": "Create or Update Template",
        "responses": {
          "201": {
            "description": "Created template"
          },
          "400": {
            "description": "Validation error"
          }
        }
      }
    },
    "/api/v1/templates/{id}": {
      "delete": {
        "summary": "Delete Template",
        "responses": {
          "200": {
            "description": "Deletion confirmation"
          },
          "403": {
            "description": "Forbidden"
          },
          "404": {
            "description": "Not found"
          }
        }
      }
    },
    "/api/v1/telemetry": {
      "get": {
        "summary": "Get Execution Telemetry Metrics",
        "responses": {
          "200": {
            "description": "Telemetry metrics summary"
          }
        }
      }
    },
    "/api/v1/nlq/translate": {
      "post": {
        "summary": "Translate Natural Language into QuerySpec AST",
        "responses": {
          "200": {
            "description": "Validated QuerySpec and confidence"
          },
          "400": {
            "description": "Translation error"
          }
        }
      }
    },
    "/api/v1/nlq/explain": {
      "post": {
        "summary": "Explain Visual Query AST in Natural Language",
        "responses": {
          "200": {
            "description": "Natural language explanation"
          },
          "400": {
            "description": "Explain error"
          }
        }
      }
    },
    "/api/v1/nlq/providers": {
      "get": {
        "summary": "List Available NLQ Providers",
        "responses": {
          "200": {
            "description": "List of available NLQ providers"
          }
        }
      }
    }
  },
  "components": {
    "schemas": {
      "VectorSearchSpec": {
        "type": "object",
        "properties": {
          "vector": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "description": "Query embedding vector"
          },
          "column": {
            "type": "string",
            "default": "embedding",
            "description": "Embedding column name"
          },
          "top_k": {
            "type": "integer",
            "default": 10,
            "description": "Max nearest neighbors to retrieve"
          },
          "metric": {
            "type": "string",
            "enum": [
              "cosine",
              "euclidean",
              "l2",
              "dot_product",
              "inner_product"
            ],
            "default": "cosine",
            "description": "Similarity / distance metric"
          },
          "include_distances": {
            "type": "boolean",
            "default": true,
            "description": "Whether to project _distance in output"
          },
          "min_score": {
            "type": "number",
            "description": "Optional similarity score threshold"
          }
        },
        "required": [
          "vector"
        ]
      },
      "HybridSearchSpec": {
        "type": "object",
        "properties": {
          "vector": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "description": "Query embedding vector"
          },
          "vector_column": {
            "type": "string",
            "default": "embedding",
            "description": "Embedding column name"
          },
          "query_text": {
            "type": "string",
            "description": "Text query for full-text search"
          },
          "text_columns": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Text columns to search against"
          },
          "alpha": {
            "type": "number",
            "default": 0.5,
            "description": "Hybrid weight (1.0 = pure vector, 0.0 = pure text)"
          },
          "fusion": {
            "type": "string",
            "enum": [
              "rrf",
              "linear"
            ],
            "default": "rrf",
            "description": "Fusion strategy"
          },
          "rrf_k": {
            "type": "integer",
            "default": 60,
            "description": "RRF smoothing factor"
          },
          "top_k": {
            "type": "integer",
            "default": 10,
            "description": "Max nearest neighbors to retrieve"
          }
        },
        "required": [
          "vector",
          "query_text",
          "text_columns"
        ]
      },
      "QuerySpec": {
        "type": "object",
        "properties": {
          "table": {
            "type": "string"
          },
          "columns": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "filters": {
            "type": "array"
          },
          "limit": {
            "type": "integer",
            "default": 50
          },
          "offset": {
            "type": "integer",
            "default": 0
          },
          "vector_search": {
            "$ref": "#/components/schemas/VectorSearchSpec"
          },
          "hybrid_search": {
            "$ref": "#/components/schemas/HybridSearchSpec"
          }
        },
        "required": [
          "table"
        ]
      },
      "QueryPlanNode": {
        "type": "object",
        "properties": {
          "node_type": {
            "type": "string"
          },
          "table": {
            "type": "string",
            "nullable": true
          },
          "cost_estimate": {
            "type": "number"
          },
          "actual_time_ms": {
            "type": "number",
            "nullable": true
          },
          "rows_estimated": {
            "type": "integer"
          },
          "rows_actual": {
            "type": "integer",
            "nullable": true
          },
          "filter_predicate": {
            "type": "string",
            "nullable": true
          },
          "index_name": {
            "type": "string",
            "nullable": true
          },
          "cost_percentage": {
            "type": "number"
          },
          "warnings": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "children": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/QueryPlanNode"
            }
          }
        },
        "required": [
          "node_type",
          "cost_estimate",
          "rows_estimated",
          "cost_percentage"
        ]
      }
    }
  }
}

